}", "new_text": "export function computeHash(entry: Omit<LedgerEntry, 'hash'>): string {
  // Deep canonical JSON: sort object keys recursively
  function sortDeep(value: any): any {
    if (Array.isArray(value)) {
      return value.map(sortDeep);
    } else if (value && typeof value === 'object') {
      const ordered: any = {};
      const keys = Object.keys(value).sort();
      for (const k of keys) {
        ordered[k] = sortDeep(value[k]);
      }
      return ordered;
    }
    return value;
  }
  const canonical = sortDeep(entry);
  const json = JSON.stringify(canonical);
  return bytesToHex(sha256(utf8ToBytes(json)));
}"}

