    const entry: LedgerEntry = { ...entryWithoutHash, hash } as LedgerEntry;
    entries.push(entry);
  };

  for (const r of receipts) {
    addImported(r.id, r);
  }
  for (const m of mileage) {
    addImported(m.id, m);
  }

